var a=[{title:`O que conta como progressão`,text:`Pode levantar um pouco mais de peso para as mesmas repetições, fazer mais repetições com o mesmo peso, acrescentar uma série que ainda consiga concluir com boa execução, usar mais amplitude ou passar para uma variação mais difícil com o peso do corpo. Um descanso mais curto concentra mais trabalho na sessão, mas pode reduzir o seu desempenho máximo de força, por isso use-o só quando serve o seu objetivo.`},{title:`Qualidade que consegue repetir`,text:`Antes de acrescentar carga, verifique se o movimento é controlado, se conclui as repetições planeadas e se o esforço corresponde ao plano. A técnica não vai parecer idêntica em todos os corpos, mas deve parecer igual para si de cada vez. Continuar a insistir enquanto a dor piora ou o movimento fica instável não é uma sobrecarga produtiva.`},{title:`Exemplo`,text:`Imagine que o objetivo são duas séries de 8–12 agachamentos goblet. Faz 10 e 9 repetições, depois 11 e 10 da vez seguinte e depois 12 e 12. Agora faz sentido um pequeno aumento de peso com menos repetições. Se os seus halteres forem de peso fixo, pode abrandar o movimento para ter mais controlo ou escolher uma variação mais difícil.`},{title:`Uma alteração de cada vez`,text:`Se aumentar ao mesmo tempo as séries, o peso, a frequência e a complexidade do exercício, torna-se difícil perceber de onde vem a sua fadiga. Altere primeiro a variável que mais importa e dê tempo ao corpo para se adaptar. O progresso abranda à medida que ganha experiência, e algumas sessões devem apenas manter o seu nível atual.`},{title:`Usar o TrainUp`,text:`A app regista as repetições que conclui, o esforço da sessão (RPE) e qualquer dor que indique. Escolhe a carga por si. Quando gera de novo o plano depois de pelo menos 3 treinos, este só fica um passo mais difícil se os seus últimos 4 treinos tiverem sido fáceis (RPE 5 ou menos) e completos. Qualquer dor recente significa que não há aumento, e se 2 dos seus últimos 3 treinos tiverem sido muito difíceis (RPE 9 ou mais) ou concluídos em menos de 60%, o plano seguinte é mais fácil.`}];var s=[{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: segurança e fundamentos do treino de resistência`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: técnica de treino com pesos (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var i={sections:a,sources:s};export{i as default,a as sections,s as sources};